import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cuda_src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <stdint.h>
#include <ATen/cuda/CUDAContext.h>

__device__ __forceinline__ float bf16_to_float(uint16_t v) {
    uint32_t u = ((uint32_t)v) << 16;
    return __uint_as_float(u);
}

__device__ __forceinline__ uint16_t float_to_bf16(float f) {
    uint32_t x = __float_as_uint(f);
    uint32_t lsb = (x >> 16) & 1u;
    uint32_t rounding_bias = 0x7fffu + lsb;
    x += rounding_bias;
    return static_cast<uint16_t>(x >> 16);
}

__global__ void conv2d_bf16_kernel(const uint16_t* __restrict__ input,
                                   const uint16_t* __restrict__ weight,
                                   uint16_t* __restrict__ output,
                                   int N, int C_in, int H, int W,
                                   int C_out, int K_h, int K_w,
                                   int stride_h, int stride_w,
                                   int pad_h, int pad_w,
                                   int H_out, int W_out) {
    int w_out = blockIdx.x * blockDim.x + threadIdx.x;
    int h_out = blockIdx.y * blockDim.y + threadIdx.y;
    int nc = blockIdx.z;
    if (w_out >= W_out || h_out >= H_out) return;
    int n = nc / C_out;
    int co = nc % C_out;
    if (n >= N) return;

    float acc = 0.0f;

    for (int ci = 0; ci < C_in; ++ci) {
        for (int kh = 0; kh < K_h; ++kh) {
            int h_in = h_out * stride_h - pad_h + kh;
            if (h_in < 0 || h_in >= H) continue;
            for (int kw = 0; kw < K_w; ++kw) {
                int w_in = w_out * stride_w - pad_w + kw;
                if (w_in < 0 || w_in >= W) continue;

                size_t in_idx = ((size_t)n * C_in + ci) * (size_t)H * (size_t)W + (size_t)h_in * (size_t)W + (size_t)w_in;
                size_t w_idx  = ((size_t)co * C_in + ci) * (size_t)K_h * (size_t)K_w + (size_t)kh * (size_t)K_w + (size_t)kw;

                float a = bf16_to_float(input[in_idx]);
                float b = bf16_to_float(weight[w_idx]);
                acc += a * b;
            }
        }
    }

    size_t out_idx = ((size_t)n * C_out + co) * (size_t)H_out * (size_t)W_out + (size_t)h_out * (size_t)W_out + (size_t)w_out;
    output[out_idx] = float_to_bf16(acc);
}
__global__ void conv2d_bf16_kernel_tiled(const uint16_t* __restrict__ input,
                                           const uint16_t* __restrict__ weight,
                                           uint16_t* __restrict__ output,
                                           int N, int C_in, int H, int W,
                                           int C_out, int K_h, int K_w,
                                           int stride_h, int stride_w,
                                           int pad_h, int pad_w,
                                           int H_out, int W_out) {
    // This tiled kernel assumes stride_h == 1, stride_w == 1, pad_h == 0, pad_w == 0
    // Dispatch only under these conditions from the host.
    const int TW = 2; // thread-level tiling in width
    const int TH = 2; // thread-level tiling in height
    int nc = blockIdx.z;
    int n = nc / C_out;
    int co = nc % C_out;
    if (n >= N) return;
    // Origin of the block's output tile
    int w_out0 = blockIdx.x * (blockDim.x * TW);
    int h_out0 = blockIdx.y * (blockDim.y * TH);
    // Per-thread starting output coordinates
    int out_x0 = w_out0 + threadIdx.x * TW;
    int out_y0 = h_out0 + threadIdx.y * TH;
    // Corresponding input origin for the tile (for stride=1, pad=0)
    int h_in0 = h_out0 * stride_h - pad_h;
    int w_in0 = w_out0 * stride_w - pad_w;
    // Shared memory layout: first input tile, then small weight tile
    extern __shared__ float smem[];
    int tile_h = blockDim.y * TH + K_h - 1;
    int tile_w = blockDim.x * TW + K_w - 1;
    int s_in_elems = tile_h * tile_w;
    float* s_in = smem;
    float* s_w  = s_in + s_in_elems; // size K_h * K_w
    // Accumulators per thread for a 2x2 output micro-tile
    float acc00 = 0.0f, acc01 = 0.0f, acc10 = 0.0f, acc11 = 0.0f;
    int linear_tid = threadIdx.y * blockDim.x + threadIdx.x;
    int threads_per_block = blockDim.x * blockDim.y;
    for (int ci = 0; ci < C_in; ++ci) {
        // Load weights for this (co, ci) into shared memory cooperatively
        int w_elems = K_h * K_w;
        for (int idx = linear_tid; idx < w_elems; idx += threads_per_block) {
            int kh = idx / K_w;
            int kw = idx - kh * K_w;
            size_t w_idx = ((size_t)co * C_in + ci) * (size_t)K_h * (size_t)K_w + (size_t)kh * (size_t)K_w + (size_t)kw;
            s_w[idx] = bf16_to_float(weight[w_idx]);
        }
        // Load input tile for this (n, ci) into shared memory cooperatively
        for (int idx = linear_tid; idx < s_in_elems; idx += threads_per_block) {
            int th = idx / tile_w;
            int tw = idx - th * tile_w;
            int h_in = h_in0 + th;
            int w_in = w_in0 + tw;
            float val = 0.0f;
            if (h_in >= 0 && h_in < H && w_in >= 0 && w_in < W) {
                size_t in_idx = ((size_t)n * C_in + ci) * (size_t)H * (size_t)W + (size_t)h_in * (size_t)W + (size_t)w_in;
                val = bf16_to_float(input[in_idx]);
            }
            s_in[idx] = val;
        }
        __syncthreads();
        // Compute for output threads using the shared tiles (2x2 outputs per thread)
        int base = (threadIdx.y * TH) * tile_w + (threadIdx.x * TW);
        #pragma unroll
        for (int kh = 0; kh < K_h; ++kh) {
            int row_off = base + kh * tile_w;
            #pragma unroll
            for (int kw = 0; kw < K_w; ++kw) {
                float a00 = s_in[row_off + kw];
                float a01 = s_in[row_off + kw + 1];
                float a10 = s_in[row_off + kw + tile_w];
                float a11 = s_in[row_off + kw + tile_w + 1];
                float b = s_w[kh * K_w + kw];
                acc00 = fmaf(a00, b, acc00);
                acc01 = fmaf(a01, b, acc01);
                acc10 = fmaf(a10, b, acc10);
                acc11 = fmaf(a11, b, acc11);
            }
        }
        __syncthreads();
    }
    // Store valid outputs
    if (out_y0 < H_out && out_x0 < W_out) {
        size_t out_idx = ((size_t)n * C_out + co) * (size_t)H_out * (size_t)W_out + (size_t)out_y0 * (size_t)W_out + (size_t)out_x0;
        output[out_idx] = float_to_bf16(acc00);
    }
    if (out_y0 < H_out && (out_x0 + 1) < W_out) {
        size_t out_idx = ((size_t)n * C_out + co) * (size_t)H_out * (size_t)W_out + (size_t)out_y0 * (size_t)W_out + (size_t)(out_x0 + 1);
        output[out_idx] = float_to_bf16(acc01);
    }
    if ((out_y0 + 1) < H_out && out_x0 < W_out) {
        size_t out_idx = ((size_t)n * C_out + co) * (size_t)H_out * (size_t)W_out + (size_t)(out_y0 + 1) * (size_t)W_out + (size_t)out_x0;
        output[out_idx] = float_to_bf16(acc10);
    }
    if ((out_y0 + 1) < H_out && (out_x0 + 1) < W_out) {
        size_t out_idx = ((size_t)n * C_out + co) * (size_t)H_out * (size_t)W_out + (size_t)(out_y0 + 1) * (size_t)W_out + (size_t)(out_x0 + 1);
        output[out_idx] = float_to_bf16(acc11);
    }
}
__global__ void conv2d_bf16_kernel_tiled_oc2(const uint16_t* __restrict__ input,
                                             const uint16_t* __restrict__ weight,
                                             uint16_t* __restrict__ output,
                                             int N, int C_in, int H, int W,
                                             int C_out, int K_h, int K_w,
                                             int stride_h, int stride_w,
                                             int pad_h, int pad_w,
                                             int H_out, int W_out) {
    // Tiled kernel computing two output channels per block to reuse input tiles
    const int TW = 2; // thread-level tiling in width
    const int TH = 2; // thread-level tiling in height
    const int OC_PER_BLOCK = 2;
    int nOCBlocks = (C_out + OC_PER_BLOCK - 1) / OC_PER_BLOCK;
    int nc_blk = blockIdx.z;
    int n = nc_blk / nOCBlocks;
    int oc_block = nc_blk % nOCBlocks;
    int co0 = oc_block * OC_PER_BLOCK;
    int co1 = co0 + 1;
    if (n >= N) return;
    // Origin of the block's output tile
    int w_out0 = blockIdx.x * (blockDim.x * TW);
    int h_out0 = blockIdx.y * (blockDim.y * TH);
    // Per-thread starting output coordinates
    int out_x0 = w_out0 + threadIdx.x * TW;
    int out_y0 = h_out0 + threadIdx.y * TH;
    // Corresponding input origin for the tile (for stride=1, pad=0)
    int h_in0 = h_out0 * stride_h - pad_h;
    int w_in0 = w_out0 * stride_w - pad_w;
    // Shared memory: input tile followed by two small weight tiles (one per co in the block)
    extern __shared__ float smem[];
    int tile_h = blockDim.y * TH + K_h - 1;
    int tile_w = blockDim.x * TW + K_w - 1;
    int s_in_elems = tile_h * tile_w;
    float* s_in = smem;
    int w_elems = K_h * K_w;
    float* s_w = s_in + s_in_elems; // size OC_PER_BLOCK * w_elems
    // Accumulators per thread for a 2x2 output micro-tile for two output channels
    float acc00_0 = 0.0f, acc01_0 = 0.0f, acc10_0 = 0.0f, acc11_0 = 0.0f;
    float acc00_1 = 0.0f, acc01_1 = 0.0f, acc10_1 = 0.0f, acc11_1 = 0.0f;
    int linear_tid = threadIdx.y * blockDim.x + threadIdx.x;
    int threads_per_block = blockDim.x * blockDim.y;
    for (int ci = 0; ci < C_in; ++ci) {
        // Load weights for two output channels for this ci into shared memory cooperatively
        for (int idx = linear_tid; idx < w_elems * OC_PER_BLOCK; idx += threads_per_block) {
            int oc_rel = idx / w_elems;
            int kidx = idx - oc_rel * w_elems;
            int kh = kidx / K_w;
            int kw = kidx - kh * K_w;
            int co = (oc_rel == 0 ? co0 : co1);
            float v = 0.0f;
            if (co < C_out) {
                size_t w_idx = ((size_t)co * C_in + (size_t)ci) * (size_t)K_h * (size_t)K_w + (size_t)kh * (size_t)K_w + (size_t)kw;
                v = bf16_to_float(weight[w_idx]);
            }
            s_w[oc_rel * w_elems + kidx] = v;
        }
        // Load input tile for this (n, ci) into shared memory cooperatively
        for (int idx = linear_tid; idx < s_in_elems; idx += threads_per_block) {
            int th = idx / tile_w;
            int tw = idx - th * tile_w;
            int h_in = h_in0 + th;
            int w_in = w_in0 + tw;
            float val = 0.0f;
            if (h_in >= 0 && h_in < H && w_in >= 0 && w_in < W) {
                size_t in_idx = ((size_t)n * C_in + (size_t)ci) * (size_t)H * (size_t)W + (size_t)h_in * (size_t)W + (size_t)w_in;
                val = bf16_to_float(input[in_idx]);
            }
            s_in[idx] = val;
        }
        __syncthreads();
        // Compute using the shared tiles (2x2 outputs per thread, for two output channels)
        int base = (threadIdx.y * TH) * tile_w + (threadIdx.x * TW);
        #pragma unroll
        for (int kh = 0; kh < K_h; ++kh) {
            int row_off = base + kh * tile_w;
            #pragma unroll
            for (int kw = 0; kw < K_w; ++kw) {
                float a00 = s_in[row_off + kw];
                float a01 = s_in[row_off + kw + 1];
                float a10 = s_in[row_off + kw + tile_w];
                float a11 = s_in[row_off + kw + tile_w + 1];
                float b0 = s_w[0 * w_elems + kh * K_w + kw];
                float b1 = s_w[1 * w_elems + kh * K_w + kw];
                acc00_0 = fmaf(a00, b0, acc00_0);
                acc01_0 = fmaf(a01, b0, acc01_0);
                acc10_0 = fmaf(a10, b0, acc10_0);
                acc11_0 = fmaf(a11, b0, acc11_0);
                acc00_1 = fmaf(a00, b1, acc00_1);
                acc01_1 = fmaf(a01, b1, acc01_1);
                acc10_1 = fmaf(a10, b1, acc10_1);
                acc11_1 = fmaf(a11, b1, acc11_1);
            }
        }
        __syncthreads();
    }
    // Store valid outputs for two output channels
    if (co0 < C_out) {
        if (out_y0 < H_out && out_x0 < W_out) {
            size_t out_idx0 = ((size_t)n * C_out + (size_t)co0) * (size_t)H_out * (size_t)W_out + (size_t)out_y0 * (size_t)W_out + (size_t)out_x0;
            output[out_idx0] = float_to_bf16(acc00_0);
        }
        if (out_y0 < H_out && (out_x0 + 1) < W_out) {
            size_t out_idx0 = ((size_t)n * C_out + (size_t)co0) * (size_t)H_out * (size_t)W_out + (size_t)out_y0 * (size_t)W_out + (size_t)(out_x0 + 1);
            output[out_idx0] = float_to_bf16(acc01_0);
        }
        if ((out_y0 + 1) < H_out && out_x0 < W_out) {
            size_t out_idx0 = ((size_t)n * C_out + (size_t)co0) * (size_t)H_out * (size_t)W_out + (size_t)(out_y0 + 1) * (size_t)W_out + (size_t)out_x0;
            output[out_idx0] = float_to_bf16(acc10_0);
        }
        if ((out_y0 + 1) < H_out && (out_x0 + 1) < W_out) {
            size_t out_idx0 = ((size_t)n * C_out + (size_t)co0) * (size_t)H_out * (size_t)W_out + (size_t)(out_y0 + 1) * (size_t)W_out + (size_t)(out_x0 + 1);
            output[out_idx0] = float_to_bf16(acc11_0);
        }
    }
    if (co1 < C_out) {
        if (out_y0 < H_out && out_x0 < W_out) {
            size_t out_idx1 = ((size_t)n * C_out + (size_t)co1) * (size_t)H_out * (size_t)W_out + (size_t)out_y0 * (size_t)W_out + (size_t)out_x0;
            output[out_idx1] = float_to_bf16(acc00_1);
        }
        if (out_y0 < H_out && (out_x0 + 1) < W_out) {
            size_t out_idx1 = ((size_t)n * C_out + (size_t)co1) * (size_t)H_out * (size_t)W_out + (size_t)out_y0 * (size_t)W_out + (size_t)(out_x0 + 1);
            output[out_idx1] = float_to_bf16(acc01_1);
        }
        if ((out_y0 + 1) < H_out && out_x0 < W_out) {
            size_t out_idx1 = ((size_t)n * C_out + (size_t)co1) * (size_t)H_out * (size_t)W_out + (size_t)(out_y0 + 1) * (size_t)W_out + (size_t)out_x0;
            output[out_idx1] = float_to_bf16(acc10_1);
        }
        if ((out_y0 + 1) < H_out && (out_x0 + 1) < W_out) {
            size_t out_idx1 = ((size_t)n * C_out + (size_t)co1) * (size_t)H_out * (size_t)W_out + (size_t)(out_y0 + 1) * (size_t)W_out + (size_t)(out_x0 + 1);
            output[out_idx1] = float_to_bf16(acc11_1);
        }
    }
}

torch::Tensor conv2d_bf16(torch::Tensor input, torch::Tensor weight,
                          int stride_h, int stride_w,
                          int pad_h, int pad_w) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(input.dtype() == torch::kBFloat16, "input must be bfloat16");
    TORCH_CHECK(weight.dtype() == torch::kBFloat16, "weight must be bfloat16");
    TORCH_CHECK(input.dim() == 4, "input must be NCHW");
    TORCH_CHECK(weight.dim() == 4, "weight must be OIHW");

    int64_t N = input.size(0);
    int64_t C_in = input.size(1);
    int64_t H = input.size(2);
    int64_t W = input.size(3);

    int64_t C_out = weight.size(0);
    int64_t K_h = weight.size(2);
    int64_t K_w = weight.size(3);

    TORCH_CHECK(weight.size(1) == C_in, "C_in mismatch between input and weight");

    int64_t H_out = (H + 2 * pad_h - K_h) / stride_h + 1;
    int64_t W_out = (W + 2 * pad_w - K_w) / stride_w + 1;
    TORCH_CHECK(H_out >= 0 && W_out >= 0, "Computed output size is negative");

    auto out = torch::empty({N, C_out, H_out, W_out}, input.options());

    dim3 block(16, 16);
    dim3 grid((W_out + block.x - 1) / block.x,
              (H_out + block.y - 1) / block.y,
              N * C_out);

    const uint16_t* in_ptr = reinterpret_cast<const uint16_t*>(input.data_ptr<at::BFloat16>());
    const uint16_t* w_ptr  = reinterpret_cast<const uint16_t*>(weight.data_ptr<at::BFloat16>());
    uint16_t* out_ptr      = reinterpret_cast<uint16_t*>(out.data_ptr<at::BFloat16>());

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();

    if (stride_h == 1 && stride_w == 1 && pad_h == 0 && pad_w == 0) {
        // Launch tiled kernel with shared memory for stride=1, pad=0 fast path, processing 2 output channels per block
        const int TW = 2;
        const int TH = 2;
        const int OC_PER_BLOCK = 2;
        int nOCBlocks = (int)((C_out + OC_PER_BLOCK - 1) / OC_PER_BLOCK);
        dim3 grid_tiled(
            (unsigned int)(((int)W_out + block.x * TW - 1) / (block.x * TW)),
            (unsigned int)(((int)H_out + block.y * TH - 1) / (block.y * TH)),
            (unsigned int)(N * nOCBlocks)
        );
        size_t smem_in_elems = (size_t)(block.y * TH + K_h - 1) * (size_t)(block.x * TW + K_w - 1);
        size_t smem_w_elems  = (size_t)K_h * (size_t)K_w * (size_t)OC_PER_BLOCK;
        size_t smem_bytes = (smem_in_elems + smem_w_elems) * sizeof(float);
        conv2d_bf16_kernel_tiled_oc2<<<grid_tiled, block, smem_bytes, stream>>>(
            in_ptr, w_ptr, out_ptr,
            (int)N, (int)C_in, (int)H, (int)W,
            (int)C_out, (int)K_h, (int)K_w,
            stride_h, stride_w,
            pad_h, pad_w,
            (int)H_out, (int)W_out
        );
        // Fallback to the naive kernel for general stride/padding
        conv2d_bf16_kernel<<<grid, block, 0, stream>>>(
            in_ptr, w_ptr, out_ptr,
            (int)N, (int)C_in, (int)H, (int)W,
            (int)C_out, (int)K_h, (int)K_w,
            stride_h, stride_w,
            pad_h, pad_w,
            (int)H_out, (int)W_out
        );
    }
    C10_CUDA_KERNEL_LAUNCH_CHECK();

    return out;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv2d_bf16", &conv2d_bf16, "Naive bf16 NCHW conv2d (CUDA)");
}
'''

_conv2d_bf16_ext = load_inline(
    name="bf16_conv2d_single_kernel_ext",
    cpp_sources=[],
    cuda_sources=[_cuda_src],
    extra_cuda_cflags=["-O2"]
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        # Initialize weights similar to nn.Conv2d default (kaiming_uniform_ with a=sqrt(5))
        self.weight = nn.Parameter(torch.empty((32, 3, 3, 3), dtype=torch.bfloat16))
        fan_in = 3 * 3 * 3
        bound = 1.0 / math.sqrt(fan_in)
        with torch.no_grad():
            self.weight.uniform_(-bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            x = x.cuda(non_blocking=True)
        if x.dtype != torch.bfloat16:
            x = x.to(dtype=torch.bfloat16)
        w = self.weight
        if not w.is_cuda:
            w = w.cuda(non_blocking=True)

        # Ensure contiguous layout for our kernel
        x = x.contiguous()
        w = w.contiguous()

        # Using stride=1, padding=0 as in the original model
        out = _conv2d_bf16_ext.conv2d_bf16(x, w, 1, 1, 0, 0)
        return out

