class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        # Initialize weights similar to nn.Conv2d default (kaiming_uniform_ with a=sqrt(5))
        self.weight = nn.Parameter(torch.empty((32, 3, 3, 3), dtype=torch.bfloat16))
        fan_in = 3 * 3 * 3
        bound = 1.0 / math.sqrt(fan_in)
        with torch.no_grad():
            self.weight.uniform_(-bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            x = x.cuda(non_blocking=True)
        if x.dtype != torch.bfloat16:
            x = x.to(dtype=torch.bfloat16)
        w = self.weight
        if not w.is_cuda:
            w = w.cuda(non_blocking=True)

        # Ensure contiguous layout for our kernel
        x = x.contiguous()
        w = w.contiguous()

        # Using stride=1, padding=0 as in the original model
        out = _conv2d_bf16_ext.conv2d_bf16(x, w, 1, 1, 0, 0)
        return out
